  ig_rn2014: {s: "INTERGROWTH-21st – tamanho ao nascer", t: "Villar J et al. International standards for newborn weight, length, and head circumference by gestational age and sex: the Newborn Cross-Sectional Study of the INTERGROWTH-21st Project. Lancet 2014;384:857-68 (33+0 a 42+6 semanas); Villar J et al. INTERGROWTH-21st very preterm size at birth reference charts. Lancet 2016 (24+0 a 32+6). Percentis 10 e 90 do peso calculados com os coeficientes publicados (pacote growthstandards) e conferidos com os valores de teste do pacote (ex.: menino 33+1: P10 1,47 kg, P90 2,56 kg) (padrão). A Caderneta da Criança 2025 usa as curvas INTERGROWTH-21st para o pré-termo.", f: "F", url: "https://doi.org/10.1016/S0140-6736(14)60932-6"},
  bula_paracetamol: {s: "Bula – paracetamol gotas e suspensão", t: "Bula de paracetamol 200 mg/mL gotas (15 gotas/mL; 13,3 mg/gota): < 12 anos, 1 gota/kg até 35 gotas por dose, a cada 4–6 h, máx. 5 vezes em 24 h; < 11 kg ou 2 anos: orientação médica. Paracetamol suspensão 32 mg/mL: 10–15 mg/kg/dose a cada 4–6 h, máx. 5 doses e 75 mg/kg/dia (bulas de genéricos consultadas em bula.com.br e Drogasil).", f: "F", url: "https://img.drogasil.com.br/raiadrogasil_bula/Paracetamol200mgPrati.pdf"},
  bula_dipirona: {s: "Bula – dipirona gotas e solução oral", t: "Bula de dipirona 500 mg/mL gotas (20 gotas/mL): 5–8 kg 2–5 gotas; 9–15 kg 3–10; 16–23 kg 5–15; 24–30 kg 8–20 gotas por dose, até 4 vezes ao dia. Solução oral 50 mg/mL: 5–8 kg 1,25–2,5 mL; 9–15 kg 2,5–5 mL; 16–23 kg 3,75–7,5 mL; 24–30 kg 5–10 mL por dose, até 4 vezes ao dia. Contraindicada em < 3 meses ou < 5 kg (bulas de genéricos, Medquímica e Germed, via drconsulta).", f: "F", url: "https://drconsulta.com/conteudo/dipirona-sodica-medquimica-bula/"},
