const GROW = (() => {
  const T = GROW_T, D = T.d;
  function lmsWho(ind, sx, dias){
    const tb = T.who[ind] && T.who[ind][sx]; if (!tb) return null;
    if (ind === "lhfa" || ind === "bfa"){ if (dias >= 729 && dias <= 730) dias = 728; else if (dias >= 731 && dias <= 734) dias = 735; }
    if (dias <= 0) return tb[0];
    let i = D.findIndex(d => d >= dias); if (i < 0) return tb[tb.length - 1];
    if (D[i] === dias) return tb[i];
    const a = D[i - 1], b = D[i], f = (dias - a) / (b - a);
    return tb[i - 1].map((v, j) => v + (tb[i][j] - v) * f);
  }
  function lms(ind, sx, dias){
    if (dias <= 1856) return lmsWho(ind, sx, dias);
    const t7 = T.who07[ind] && T.who07[ind][sx]; if (!t7) return null;
    const mo = Math.min(Math.max(dias / 30.4375, 61), 72), i = Math.floor(mo) - 61, f = mo - Math.floor(mo);
    if (i >= t7.length - 1) return t7[t7.length - 1];
    return t7[i].map((v, j) => v + (t7[i + 1][j] - v) * f);
  }
  function z(ind, sx, dias, y){
    const r = lms(ind, sx, dias); if (!r || !(y > 0)) return null;
    const [L, M, S] = r; const v = x => M * Math.pow(1 + L * S * x, 1 / L);
    let zz = Math.abs(L) < 1e-9 ? Math.log(y / M) / S : (Math.pow(y / M, L) - 1) / (L * S);
    if ((ind === "wfa" || ind === "bfa") && zz > 3){ const s3 = v(3), s23 = s3 - v(2); zz = 3 + (y - s3) / s23; }
    if ((ind === "wfa" || ind === "bfa") && zz < -3){ const s3 = v(-3), s23 = v(-2) - s3; zz = -3 - (s3 - y) / s23; }
    return zz;
  }
  // classificação SISVAN 2011 (escore-z)
  function classe(ind, zz, meses){
    if (zz == null) return "";
    if (ind === "wfa") return zz < -3 ? "muito baixo peso para a idade" : zz < -2 ? "baixo peso para a idade" : zz > 2 ? "peso elevado para a idade" : "peso adequado para a idade";
    if (ind === "lhfa") return zz < -3 ? "muito baixa estatura para a idade" : zz < -2 ? "baixa estatura para a idade" : "estatura adequada para a idade";
    if (ind === "hcfa") return zz < -2 ? "PC abaixo de −2 escore-z" : zz > 2 ? "PC acima de +2 escore-z" : "PC adequado para a idade";
    if (meses < 60) return zz < -3 ? "magreza acentuada" : zz < -2 ? "magreza" : zz <= 1 ? "eutrofia" : zz <= 2 ? "risco de sobrepeso" : zz <= 3 ? "sobrepeso" : "obesidade";
    return zz < -3 ? "magreza acentuada" : zz < -2 ? "magreza" : zz <= 1 ? "eutrofia" : zz <= 2 ? "sobrepeso" : zz <= 3 ? "obesidade" : "obesidade grave";
  }
  // peso ao nascer × IG (INTERGROWTH-21st): AIG = P10–P90
  function ig(sexo, gaDias, pesoG){
    if (!(gaDias >= 168 && gaDias <= 300) || !(pesoG > 0)) return null;
    const cl = s => { const r = T.ig[s][gaDias - 168]; return pesoG < r[0] ? "PIG" : pesoG > r[1] ? "GIG" : "AIG"; };
    if (sexo === "m") return {c: cl("Male"), p: T.ig.Male[gaDias - 168]};
    if (sexo === "f") return {c: cl("Female"), p: T.ig.Female[gaDias - 168]};
    const a = cl("Male"), b = cl("Female"); return a === b ? {c: a, p: null} : {c: null, p: null};
  }
  return {z, classe, ig};
})();
